// SignInRequest defines model for SignInRequest.
type SignInRequest struct {
	// Credential A member number or a phone number.
	Credential string `json:"credential"`

	// DeviceToken NON-BROWSER CLIENTS ONLY: the token this server issued to this
	// device on an earlier sign-in; absent on a new device. A browser
	// sends none (its device rides in the __Secure-argon_device cookie):
	// a request with an Origin that carries one is refused, 400
	// device_token_from_browser, before the PIN is checked.
	DeviceToken *string `json:"deviceToken,omitempty"`
	Pin         string  `json:"pin"`

	// Surface Which surface the client is. INFORMATIONAL ONLY; it never sets the session's length.
	Surface *SignInRequestSurface `json:"surface,omitempty"`
}

// SignInRequestSurface Which surface the client is. INFORMATIONAL ONLY; it never sets the session's length.
type SignInRequestSurface string

// SignInResult defines model for SignInResult.
type SignInResult struct {
	// Challenge code_sent only. Never contains or implies the code.
	Challenge *string `json:"challenge,omitempty"`

	// CsrfToken signed_in, BROWSER callers only (an Origin was sent): sent back as
	// X-CSRF-Token on every state-changing request of this session. Hold
	// it in memory only, never in storage, a cookie or a URL; after a
	// reload, GET /me returns it again.
	CsrfToken *string `json:"csrfToken,omitempty"`

	// DeviceToken Issued when a new device becomes trusted; NON-BROWSER callers only.
	// A browser's device is the __Secure-argon_device cookie.
	DeviceToken *string `json:"deviceToken,omitempty"`

	// ExpiresAt signed_in only. 8 hours for anyone holding a post, 30 days otherwise.
	ExpiresAt *time.Time          `json:"expiresAt,omitempty"`
	Message   *string             `json:"message,omitempty"`
	Outcome   SignInResultOutcome `json:"outcome"`

	// Reason see_officer only: why. "ambiguous" — the credential matches more
	// than one person; "no_agreed_number" — no single registered number
	// to send a code to; "sms_unavailable" — TEMPORARY: codes cannot be
	// sent yet (no SMS provider), so a new device goes to an officer.
	Reason *string `json:"reason,omitempty"`

	// SessionToken signed_in, NON-BROWSER callers only (no Origin). A browser's
	// session is the __Host-argon_session cookie and is never in a body.
	SessionToken *string `json:"sessionToken,omitempty"`
}

// SignInResultOutcome defines model for SignInResult.Outcome.
type SignInResultOutcome string

// StatementRow defines model for StatementRow.
type StatementRow struct {
	AdjustsEntryId *openapi_types.UUID `json:"adjustsEntryId"`

	// Charges Every charge line of the entry, each component separately, IN THIS
	// ORDER: partner_charge, argon_margin, vat, statutory_levy (what the
	// bank took, what Argon took, the tax on Argon's charge, the levy).
	// Only the non-zero components appear; the order of those that do is
	// fixed, and a client may render the list as sent. Empty when the
	// movement is free.
	Charges []ChargeLine `json:"charges"`

	// Direction Relative to the member's SAVINGS: "in" when their savings rose. Read
	// from the member's savings line, never from a bank line (an internal
	// transfer has none).
	Direction StatementRowDirection `json:"direction"`
	EntryId   openapi_types.UUID    `json:"entryId"`

	// GrossKobo A NON-NEGATIVE amount in kobo: "how much", not a signed line. Used for a
	// movement's size (gross). LEDGER_CONTRACT.md §0: a movement's amount is a
	// magnitude; only a LINE carries a sign.
	GrossKobo Magnitude `json:"grossKobo"`

	// Kind Every movement of money in the product. Mirrors the movement_kind enum
	// in the database and the MovementKind union in the frontend; all three
	// are generated from this.
	//
	// opening_balance and payroll_remittance carry NO CHARGE. opening_balance
	// is free deliberately, not by oversight: charging on a migration takes a
	// cut of money that was in the society's books before Argon existed. It is
	// also not a contribution — a member's statement must not say they
	// contributed on the day the software changed.
	Kind     MovementKind `json:"kind"`
	PostedAt time.Time    `json:"postedAt"`

	// PostedBy NULL in the member projection; present in the officer projection. Frozen at posting (§4).
	PostedBy *PostedBy `json:"postedBy"`

	// Reason Why a reversal or adjustment was made. Shown to the member; it is their money.
	Reason *string `json:"reason"`

	// Reference The batch reference (an import's client-minted key), if any.
	Reference       *string             `json:"reference"`
	ReversesEntryId *openapi_types.UUID `json:"reversesEntryId"`

	// SavingsBalanceKobo A BALANCE, FROM THE MEMBER'S SIDE — NOT a §0 line. Positive means the
	// society owes the member this much (they are in credit). Lines follow §0
	// (positive = debit), so the member's savings lines that build this
	// balance are negative; this field is their negation, computed once, here,
	// so no client ever negates anything. Decided 2026-10-01.
	SavingsBalanceKobo SavingsBalance `json:"savingsBalanceKobo"`

	// SavingsLineKobo An amount in kobo. ₦1 = 100 kobo. A STRING because a JSON number is a
	// float. Positive is a debit, negative a credit.
	SavingsLineKobo Kobo `json:"savingsLineKobo"`

	// ValueDate The society's as-at date for this movement. NULL means the society's
	// records carry no as-at date: render it as "accumulated before
	// migration", NEVER as a blank, and never substitute postedAt. A blank
	// reads as a bug; a stated unknown reads as a fact.
	ValueDate *openapi_types.Date `json:"valueDate"`
}

// StatementRowDirection Relative to the member's SAVINGS: "in" when their savings rose. Read
// from the member's savings line, never from a bank line (an internal
// transfer has none).
type StatementRowDirection string

// TrialBalance Every account of the society (the same set as the chart, zero rows
// included), as at the end of asOf by value date. totalDebitsKobo +
// totalCreditsKobo is ZERO, by construction. If the books ever do not sum
// to zero, the server does not return a trial balance with a variance: it
// refuses with 500 ledger_does_not_balance. That is a defect, never a
// figure to display.
type TrialBalance struct {
	AsOf openapi_types.Date `json:"asOf"`

	// Rows Ordered by account code.
	Rows      []TrialBalanceRow  `json:"rows"`
	SocietyId openapi_types.UUID `json:"societyId"`

	// TotalCreditsKobo An amount in kobo. ₦1 = 100 kobo. A STRING because a JSON number is a
	// float. Positive is a debit, negative a credit.
	TotalCreditsKobo Kobo `json:"totalCreditsKobo"`

	// TotalDebitsKobo An amount in kobo. ₦1 = 100 kobo. A STRING because a JSON number is a
	// float. Positive is a debit, negative a credit.
	TotalDebitsKobo Kobo `json:"totalDebitsKobo"`
}

// TrialBalanceRow One account's turnover and balance. debitsKobo is the sum of its debit
// lines (>= 0), creditsKobo the sum of its credit lines (<= 0, SIGNED, so
// debits + credits = balance is a plain sum). Both are shown even when
// they cancel: a reversed contribution is a debit AND a credit, not nothing.
type TrialBalanceRow struct {
	// BalanceKobo An amount in kobo. ₦1 = 100 kobo. A STRING because a JSON number is a
	// float. Positive is a debit, negative a credit.
	BalanceKobo Kobo   `json:"balanceKobo"`
	Code        string `json:"code"`

	// CreditsKobo An amount in kobo. ₦1 = 100 kobo. A STRING because a JSON number is a
	// float. Positive is a debit, negative a credit.
	CreditsKobo Kobo `json:"creditsKobo"`

	// DebitsKobo An amount in kobo. ₦1 = 100 kobo. A STRING because a JSON number is a
	// float. Positive is a debit, negative a credit.
	DebitsKobo Kobo        `json:"debitsKobo"`
	Kind       AccountKind `json:"kind"`
	Name       string      `json:"name"`
}

// VerifyCodeRequest defines model for VerifyCodeRequest.
type VerifyCodeRequest struct {
	Challenge string `json:"challenge"`
	Code      string `json:"code"`
}

// Withdrawable A member's savings and what they may withdraw now. The withdrawable
// figure is the savings less every deduction, never below zero, and A
// WITHDRAWAL'S CHARGE COMES OUT OF IT: a request is accepted when the
// amount and its charge together fit (0016 checks exactly this when it is
// raised, and the hold again before money moves). Ask
// GET /members/{id}/withdrawal-quote for a given amount.
type Withdrawable struct {
	AsOf time.Time `json:"asOf"`

	// Deductions Everything deducted, with why. Empty, never null.
	Deductions []Deduction `json:"deductions"`

	// LargestRequestableKobo THE LARGEST AMOUNT THE MEMBER CAN ASK FOR NOW, its charge fitting
	// inside withdrawableKobo: the database's largest_withdrawal (0017),
	// which prices every amount with the rule a raise is checked by, so
	// it is EXACT at a band boundary (never withdrawable less the charge
	// on withdrawable). Accepted when raised; one kobo more is refused.
	// NULL exactly when withdrawableKobo is NULL (unavailable says why);
	// 0 when nothing fits, never negative.
	LargestRequestableKobo *Magnitude         `json:"largestRequestableKobo"`
	MemberId               openapi_types.UUID `json:"memberId"`

	// Requested Withdrawals the member has REQUESTED and no officer has authorised
	// yet. NOT DEDUCTED: a request is a question; the hold is where money
	// is committed (LEDGER_CONTRACT.md §12). A request leaves this list
	// when it is authorised (it becomes the authorised_payout deduction),
	// refused, expired or withdrawn, so no amount is ever both here and
	// deducted. Empty, never null.
	Requested []RequestedWithdrawal `json:"requested"`

	// SavingsBalanceKobo A BALANCE, FROM THE MEMBER'S SIDE — NOT a §0 line. Positive means the
	// society owes the member this much (they are in credit). Lines follow §0
	// (positive = debit), so the member's savings lines that build this
	// balance are negative; this field is their negation, computed once, here,
	// so no client ever negates anything. Decided 2026-10-01.
	SavingsBalanceKobo SavingsBalance `json:"savingsBalanceKobo"`

	// Unavailable Why withdrawableKobo is NULL (floor_unset), in words to show. NULL when it is shown.
	Unavailable *Problem `json:"unavailable"`

	// WithdrawableKobo NULL when it cannot be worked out; `unavailable` says why.
	WithdrawableKobo *Magnitude `json:"withdrawableKobo"`
}

// WithdrawalQuote WHAT A WITHDRAWAL OF THIS AMOUNT WOULD COST TODAY. INDICATIVE, NOT
// BINDING: the charge that applies is fixed when the payout is authorised
// (its hold), from the society's series in force that day, and is shown
// on the request (authorisedCharges). If the series changes between the
// two, the hold's figure applies.
type WithdrawalQuote struct {
	// AmountKobo A NON-NEGATIVE amount in kobo: "how much", not a signed line. Used for a
	// movement's size (gross). LEDGER_CONTRACT.md §0: a movement's amount is a
	// magnitude; only a LINE carries a sign.
	AmountKobo Magnitude `json:"amountKobo"`

	// Charges A movement's charges, AS THE SERVER COMPUTED THEM (0011, 0013): the
	// society's series in force on the date, four components, never summed
	// into one figure but totalled for convenience. A client never supplies a
	// charge; one sent in a body is ignored.
	Charges Charges `json:"charges"`

	// Indicative Always true. Present so that no client can mistake a quote for the charge.
	Indicative bool               `json:"indicative"`
	MemberId   openapi_types.UUID `json:"memberId"`

	// Note The sentence to show beside a quote, saying it is indicative and when the figure is fixed.
	Note     string             `json:"note"`
	QuotedOn openapi_types.Date `json:"quotedOn"`

	// TotalOutKobo A NON-NEGATIVE amount in kobo: "how much", not a signed line. Used for a
	// movement's size (gross). LEDGER_CONTRACT.md §0: a movement's amount is a
	// magnitude; only a LINE carries a sign.
	TotalOutKobo Magnitude `json:"totalOutKobo"`

	// WithdrawableUnavailable Why withinWithdrawable is NULL, the same reason /withdrawable gives
	// (floor_unset), in words to show BESIDE the fee: without it a
	// confident fee reads as the live part of the screen and the blank
	// beside it as a loading state. NULL when withinWithdrawable is set.
	WithdrawableUnavailable *Problem `json:"withdrawableUnavailable"`

	// WithinWithdrawable Whether the total fits the member's withdrawable figure now. NULL
	// when that figure cannot be worked out: "we cannot tell whether this
	// fits", never "it does not fit". withdrawableUnavailable then says why.
	WithinWithdrawable *bool `json:"withinWithdrawable"`
}

